begin;
select no_plan();
create function pg_temp.id(n integer) returns uuid language sql immutable as $$select ('ba240000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.login(n integer,org integer) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'role','authenticated','org_id',pg_temp.id(org))::text,true)::void$$;
insert into auth.users(id,email) select pg_temp.id(n),'population-'||n||'@test.local' from generate_series(10,16) n;
insert into public.organizations(id,slug,name) values(pg_temp.id(1),'population-a','Population A'),(pg_temp.id(2),'population-b','Population B');
insert into public.memberships(organization_id,user_id,role) values
 (pg_temp.id(1),pg_temp.id(10),'owner'),(pg_temp.id(1),pg_temp.id(11),'viewer'),(pg_temp.id(1),pg_temp.id(12),'branch_user'),
 (pg_temp.id(2),pg_temp.id(13),'owner'),(pg_temp.id(1),pg_temp.id(14),'planner'),(pg_temp.id(1),pg_temp.id(15),'approver'),(pg_temp.id(1),pg_temp.id(16),'admin');
insert into public.locations(id,organization_id,code,name_en,location_type,country_code,timezone)
 select pg_temp.id(20+n),pg_temp.id(case when n=2 then 2 else 1 end),'L'||n,'Location','branch','SA','Asia/Riyadh' from generate_series(0,2) n;
insert into public.items(id,organization_id,code,name_en,product_group,unit_of_measure,unit_cost,currency)
 values(pg_temp.id(30),pg_temp.id(1),'P1','Part','Test','EA',1,'SAR');
insert into public.membership_locations values(pg_temp.id(1),pg_temp.id(12),pg_temp.id(21));
create temporary table fixture(input jsonb,report jsonb,saved uuid);
insert into fixture(input) values('{"item_code": "P1", "location_code": "L0", "dataset_name": "Equipment population", "unit": "EA", "source": "Synthetic source", "as_of": "2026-01-02", "available_on": "2026-01-03", "confirmed": true, "non_overlapping": true, "rows": [{"group_code": "A", "group_name": "Known", "installed_on": "2026-01-01", "active_assets": "12", "parts_per_asset": "2.5"}, {"group_code": "B", "group_name": "Unknown", "installed_on": null, "active_assets": "3", "parts_per_asset": "0.001"}, {"group_code": "C", "group_name": "Zero", "installed_on": null, "active_assets": "0", "parts_per_asset": "1"}]}');
grant all on fixture to authenticated;
create function pg_temp.preview(overrides jsonb default '{}') returns jsonb language sql as $$select public.installed_base_preview(pg_temp.id(1),input||overrides) from fixture$$;
create function pg_temp.save(n integer default 40, overrides jsonb default '{}', fingerprint text default null) returns uuid language sql as $$select public.installed_base_save(pg_temp.id(1),input||overrides,pg_temp.id(n),coalesce(fingerprint,report->>'fingerprint')) from fixture$$;
select pg_temp.login(10,1); set local role authenticated;
update fixture set report=pg_temp.preview();
select is((select report#>>'{totals,active_assets}' from fixture),'15','exact total assets');
select is((select report#>>'{totals,installed_quantity}' from fixture),'30.003','exact fitted quantities');
select is((select report#>>'{totals,known_age_assets}' from fixture),'12','known age population');
select is((select report#>>'{totals,unknown_age_assets}' from fixture),'3','unknown age population');
select is((select report#>>'{groups,0,age_days}' from fixture),'1','elapsed calendar days at as-of');
select is((select report#>'{groups,1,age_days}' from fixture),'null'::jsonb,'missing age remains unknown');
select is((select report#>>'{groups,2,installed_quantity}' from fixture),'0','zero population contributes zero');
select is((select report#>>'{input,available_on}' from fixture),'2026-01-03','source availability retained separately');
select is(pg_temp.preview('{"confirmed":false}')#>>'{input,confirmed}','false','unconfirmed preview is inspectable');
select throws_ok($$select pg_temp.save(40,'{"confirmed":false}')$$,'MQ422','invalid population save','source confirmation required');
select throws_ok($$select pg_temp.save(40,'{"non_overlapping":false}')$$,'MQ422','invalid population save','non-overlap confirmation required');
select throws_ok($$select pg_temp.preview('{"rows": []}')$$,'MQ422','invalid population dates or group count','reject invalid input case 1');
select throws_ok($$select pg_temp.preview('{"rows": null}')$$,'MQ422','invalid population input','reject invalid input case 2');
select throws_ok($$select pg_temp.preview('{"unit": 42}')$$,'MQ422','invalid population metadata','reject invalid input case 3');
select throws_ok($$select pg_temp.preview('{"unit": " "}')$$,'MQ422','invalid population metadata','reject invalid input case 4');
select throws_ok($$select pg_temp.preview('{"unit": "BOX"}')$$,'MQ422','population unit must match catalog part','reject invalid input case 5');
select throws_ok($$select pg_temp.preview('{"as_of": "2026-02-30"}')$$,'MQ422','invalid population dates','reject invalid input case 6');
select throws_ok($$select pg_temp.preview('{"as_of": "0000-01-01"}')$$,'MQ422','invalid population dates','reject invalid input case 7');
select throws_ok($$select pg_temp.preview('{"available_on": "2026-01-01"}')$$,'MQ422','invalid population dates or group count','reject invalid input case 8');
select throws_ok($$select pg_temp.preview('{"available_on": "9999-12-31"}')$$,'MQ422','population evidence cannot be in the future','reject invalid input case 9');
select throws_ok($$select pg_temp.preview('{"confirmed": null}')$$,'MQ422','invalid population input','reject invalid input case 10');
select throws_ok($$select pg_temp.preview('{"non_overlapping": null}')$$,'MQ422','invalid population input','reject invalid input case 11');
select throws_ok($$select pg_temp.preview('{"rows": [{"group_code": "A", "group_name": "Known", "installed_on": "2026-01-01", "active_assets": "1.2", "parts_per_asset": "2.5"}]}')$$,'MQ422','invalid population group','reject invalid input case 12');
select throws_ok($$select pg_temp.preview('{"rows": [{"group_code": "A", "group_name": "Known", "installed_on": "2026-01-01", "active_assets": 12, "parts_per_asset": "2.5"}]}')$$,'MQ422','invalid population group','reject invalid input case 13');
select throws_ok($$select pg_temp.preview('{"rows": [{"group_code": "A", "group_name": "Known", "installed_on": "2026-01-01", "active_assets": "-1", "parts_per_asset": "2.5"}]}')$$,'MQ422','invalid population group','reject invalid input case 14');
select throws_ok($$select pg_temp.preview('{"rows": [{"group_code": "A", "group_name": "Known", "installed_on": "2026-01-01", "active_assets": "1000000000000000", "parts_per_asset": "2.5"}]}')$$,'MQ422','invalid population group','reject invalid input case 15');
select throws_ok($$select pg_temp.preview('{"rows": [{"group_code": "A", "group_name": "Known", "installed_on": "2026-01-01", "active_assets": "12", "parts_per_asset": "0"}]}')$$,'MQ422','invalid population group','reject invalid input case 16');
select throws_ok($$select pg_temp.preview('{"rows": [{"group_code": "A", "group_name": "Known", "installed_on": "2026-01-01", "active_assets": "12", "parts_per_asset": "NaN"}]}')$$,'MQ422','invalid population group','reject invalid input case 17');
select throws_ok($$select pg_temp.preview('{"rows": [{"group_code": "A", "group_name": "Known", "installed_on": "2026-01-01", "active_assets": "12", "parts_per_asset": "1e2"}]}')$$,'MQ422','invalid population group','reject invalid input case 18');
select throws_ok($$select pg_temp.preview('{"rows": [{"group_code": "A", "group_name": "Known", "installed_on": "2026-01-01", "active_assets": "12", "parts_per_asset": "1.0001"}]}')$$,'MQ422','invalid population group','reject invalid input case 19');
select throws_ok($$select pg_temp.preview('{"rows": [{"group_code": "A", "group_name": "Known", "installed_on": "2026-01-01", "active_assets": "12", "parts_per_asset": "1000000000000000"}]}')$$,'MQ422','invalid population group','reject invalid input case 20');
select throws_ok($$select pg_temp.preview('{"rows": [{"group_code": " ", "group_name": "Known", "installed_on": "2026-01-01", "active_assets": "12", "parts_per_asset": "2.5"}]}')$$,'MQ422','invalid population group','reject invalid input case 21');
select throws_ok($$select pg_temp.preview('{"rows": [{"group_code": "A", "group_name": "", "installed_on": "2026-01-01", "active_assets": "12", "parts_per_asset": "2.5"}]}')$$,'MQ422','invalid population group','reject invalid input case 22');
select throws_ok($$select pg_temp.preview('{"rows": [{"group_code": "A", "group_name": "Known", "installed_on": "2026-02-30", "active_assets": "12", "parts_per_asset": "2.5"}]}')$$,'MQ422','invalid population dates','reject invalid input case 23');
select throws_ok($$select pg_temp.preview('{"rows": [{"group_code": "A", "group_name": "Known", "installed_on": "", "active_assets": "12", "parts_per_asset": "2.5"}]}')$$,'MQ422','invalid population dates','reject invalid input case 24');
select throws_ok($$select pg_temp.preview('{"rows": [{"group_code": "A", "group_name": "Known", "installed_on": 42, "active_assets": "12", "parts_per_asset": "2.5"}]}')$$,'MQ422','invalid population dates','reject invalid input case 25');
select throws_ok($$select pg_temp.preview('{"rows": [{"group_code": "A", "group_name": "Known", "installed_on": "0000-01-01", "active_assets": "12", "parts_per_asset": "2.5"}]}')$$,'MQ422','invalid population dates','reject invalid input case 26');
select throws_ok($$select pg_temp.preview('{"rows": [{"group_code": "A", "group_name": "Known", "installed_on": "2026-01-03", "active_assets": "12", "parts_per_asset": "2.5"}]}')$$,'MQ422','installation after population date','reject invalid input case 27');
select throws_ok($$select pg_temp.preview('{"rows": [{"group_code": "A", "group_name": "Known", "installed_on": "2026-01-01", "active_assets": "12", "parts_per_asset": "2.5"}, {"group_code": " A ", "group_name": "Known", "installed_on": "2026-01-01", "active_assets": "12", "parts_per_asset": "2.5"}]}')$$,'MQ422','duplicate population groups','reject invalid input case 28');
select throws_ok($$select pg_temp.preview('{"rows": [{"group_code": "A", "group_name": "Known", "active_assets": "12", "parts_per_asset": "2.5"}]}')$$,'MQ422','invalid population group','reject invalid input case 29');
select throws_ok($$select public.installed_base_preview(pg_temp.id(1),'null')$$,'MQ422','invalid population input','scalar input rejected');
select throws_ok($$select pg_temp.preview(jsonb_build_object('source',repeat('x',525000)))$$,'MQ422','invalid population input','input bytes bounded');
select throws_ok($$select pg_temp.preview(jsonb_build_object('rows',(select jsonb_agg(jsonb_build_object('group_code',n::text,'group_name','Group','installed_on',null,'active_assets','1','parts_per_asset','1')) from generate_series(1,1001) n)))$$,'MQ422','invalid population dates or group count','group count bounded');
select is(pg_temp.preview('{"rows":[{"group_code":"MAX","group_name":"Large","installed_on":null,"active_assets":"999999999999999","parts_per_asset":"999999999999999.999"}]}')#>>'{totals,installed_quantity}',trim_scale(999999999999999::numeric*999999999999999.999)::text,'large exact product beyond source precision');
update fixture set saved=pg_temp.save();
select is(pg_temp.save(),(select saved from fixture),'identical retry returns saved dataset');
select is(pg_temp.save(40,jsonb_build_object('rows',jsonb_build_array(input#>'{rows,2}',input#>'{rows,0}',input#>'{rows,1}'))),(select saved from fixture),'row ordering does not change retry identity') from fixture;
select is(pg_temp.save(40,jsonb_build_object('rows',jsonb_set(input->'rows','{0,active_assets}','"0012"') || '[]'::jsonb)),(select saved from fixture),'equivalent exact count spelling retries canonically') from fixture;
select throws_ok($$select pg_temp.save(40,'{"dataset_name":"Different"}')$$,'MQ409','population request conflicts','conflicting retry rejected');
select throws_ok($$select pg_temp.save(41,'{}',repeat('a',64))$$,'MQ409','population evidence changed; refresh preview','forged preview rejected');
select is((select count(*)::integer from public.installed_base_datasets),1,'only one dataset stored');
select ok((select created_at <= clock_timestamp() and created_at >= transaction_timestamp() from public.installed_base_datasets),'server assigns import timestamp');
select throws_ok($$insert into public.installed_base_datasets default values$$,'42501',null,'direct insert denied');
select throws_ok($$update public.installed_base_datasets set dataset_name='x'$$,'42501',null,'direct updates denied');
select throws_ok($$delete from public.installed_base_datasets$$,'42501',null,'direct deletion denied');
select throws_ok($$select app.installed_base_input('{}')$$,'42501',null,'private normalizer not exposed');
select pg_temp.login(11,1);
select is((select count(*)::integer from public.installed_base_datasets),1,'viewer reads history');
select throws_ok($$select pg_temp.save()$$,'MQ403','population save forbidden','viewer cannot retry a save');
select pg_temp.login(15,1);
select throws_ok($$select pg_temp.save()$$,'MQ403','population save forbidden','approver cannot save');
select pg_temp.login(12,1);
select is((select count(*)::integer from public.installed_base_datasets),0,'restricted branch cannot read other location');
select throws_ok($$select pg_temp.preview()$$,'MQ404','population source unavailable','definer preview enforces branch scope');
select pg_temp.login(13,2);
select is((select count(*)::integer from public.installed_base_datasets),0,'other tenant cannot read datasets');
select throws_ok($$select pg_temp.save()$$,'MQ403','population save forbidden','cross tenant save denied');
select pg_temp.login(10,2);
select throws_ok($$select pg_temp.preview()$$,'MQ404','population source unavailable','active organization mismatch denied');
reset role;
insert into public.membership_locations values(pg_temp.id(1),pg_temp.id(12),pg_temp.id(20));
select pg_temp.login(12,1); set local role authenticated;
select is((select count(*)::integer from public.installed_base_datasets),1,'branch reads after scope granted');
reset role;
update public.items set name_en='Changed' where id=pg_temp.id(30);
select pg_temp.login(10,1); set local role authenticated;
select throws_ok($$select pg_temp.save(42)$$,'MQ409','population evidence changed; refresh preview','changed catalog evidence needs refresh');
select is(pg_temp.save(),(select saved from fixture),'historical retry remains stable after catalog change');
select is((select report#>>'{source,item_name}' from public.installed_base_datasets),'Part','saved catalog evidence fixed');
update fixture set report=pg_temp.preview();
select pg_temp.login(14,1);
select lives_ok($$select pg_temp.save(43)$$,'planner saves new dataset');
select pg_temp.login(16,1);
select lives_ok($$select pg_temp.save(44)$$,'admin saves new dataset');
reset role;
delete from public.items where id=pg_temp.id(30);
select pg_temp.login(10,1); set local role authenticated;
select is((select count(*)::integer from public.installed_base_datasets),3,'datasets survive item deletion');
select is(pg_temp.save(40,'{}',(select report->>'fingerprint' from public.installed_base_datasets where id=(select saved from fixture))),(select saved from fixture),'retry original remains independent of item deletion');
select is((select count(*)::integer from public.planning_runs where organization_id=pg_temp.id(1)),0,'no forecasts queued');
select is((select count(*)::integer from public.inventory_policies where organization_id=pg_temp.id(1)),0,'no policies created');
select is((select count(*)::integer from public.open_orders where organization_id=pg_temp.id(1)),0,'no orders created');
reset role;
update public.memberships set role='viewer' where organization_id=pg_temp.id(1) and user_id=pg_temp.id(10);
select pg_temp.login(10,1); set local role authenticated;
select throws_ok($$select pg_temp.save()$$,'MQ403','population save forbidden','revoked editor cannot retry');
reset role;
delete from public.locations where id=pg_temp.id(20);
select is((select count(*)::integer from public.installed_base_datasets),0,'location deletion cascades datasets');
select * from finish();
rollback;
